// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint256 _value, bytes memory _data) public {
        // Bound the value to a reasonable amount
        _value = bound(_value, 0, address(c).balance);
        // Fund the contract with some ether if needed
        vm.deal(address(c), _value);
        // Call sendMoney
        c.sendMoney(_target, _value, _data);
        // The owner must always be the deployer (address(this) in setUp)
        assertTrue(c.owner() == address(this));
    }
}

